META = dict(nama="Auto Maintenance", jp="自動車整備", emoji="🔧", co="自動車整備工場")
SPEC = dict(kerja="お客様の車を安全に整備している", kerja_id="merawat mobil pelanggan dengan aman", soal={
 "shibou-01": ("なぜ自動車整備の仕事を選びましたか。", "Mengapa Anda memilih pekerjaan perawatan mobil?", "小さいころから車が好きで、エンジンの仕組みに興味がありました。車を直す仕事がしたいです。", "Sejak kecil saya suka mobil dan tertarik pada cara kerja mesin. Saya ingin bekerja memperbaiki mobil.", [("整備", "perawatan/servis"), ("エンジン", "mesin"), ("仕組み", "mekanisme"), ("直す", "memperbaiki")]),
 "shibou-02": ("なぜ日本で自動車整備を学びたいですか。", "Mengapa Anda ingin belajar perawatan mobil di Jepang?", "日本の車は品質が高くて、整備の技術もとても進んでいると聞きました。その技術を学びたいです。", "Saya dengar mobil Jepang berkualitas tinggi dan teknik servisnya sangat maju. Saya ingin mempelajari teknik itu.", [("技術", "teknik"), ("品質", "kualitas"), ("進んでいる", "maju"), ("学ぶ", "belajar")]),
 "shibou-04": ("この仕事に興味を持った理由は何ですか。", "Apa alasan Anda tertarik pada pekerjaan ini?", "車が直って、お客様が喜んでくれると、とてもうれしいと思います。人の役に立つ仕事がしたいです。", "Saya kira sangat menyenangkan bila mobil sudah beres dan pelanggan senang. Saya ingin bekerja yang berguna bagi orang.", [("興味", "minat"), ("お客様", "pelanggan"), ("役に立つ", "berguna"), ("やりがい", "rasa bermakna")]),
 "shibou-05": ("自動車整備の仕事で、一番楽しみなことは何ですか。", "Apa yang paling Anda nantikan dari pekerjaan perawatan mobil?", "原因が分からなかった故障が直ったときの喜びです。日本の新しい車の技術も見てみたいです。", "Kegembiraan saat kerusakan yang tidak diketahui penyebabnya berhasil diperbaiki. Saya juga ingin melihat teknologi mobil baru Jepang.", [("故障", "kerusakan"), ("原因", "penyebab"), ("楽しみ", "dinantikan")]),
 "shigoto-01": ("自動車整備の主な仕事は何だと思いますか。", "Menurut Anda, apa pekerjaan utama perawatan mobil?", "車の点検をしたり、オイルやタイヤを交換したり、故障を直したりする仕事だと思います。", "Saya kira pekerjaannya memeriksa mobil, mengganti oli dan ban, serta memperbaiki kerusakan.", [("点検", "inspeksi"), ("交換", "penggantian"), ("オイル", "oli"), ("タイヤ", "ban")]),
 "shigoto-02": ("工場の仕事は、朝何時から始まると思いますか。", "Menurut Anda, jam berapa pekerjaan bengkel dimulai?", "朝八時ごろから始まると思います。早く着いて、準備をします。", "Saya kira mulai sekitar jam delapan pagi. Saya akan datang lebih awal dan bersiap.", [("始まる", "dimulai"), ("準備", "persiapan"), ("早く着く", "datang lebih awal")]),
 "shigoto-03": ("立ったままや、しゃがんだままで、長く作業できますか。", "Bisakah Anda bekerja lama dalam posisi berdiri atau jongkok?", "はい、できます。ときどき姿勢を変えて、体を伸ばしながら作業します。", "Ya, bisa. Saya sesekali mengubah posisi dan meregangkan badan sambil bekerja.", [("しゃがむ", "jongkok"), ("姿勢", "postur"), ("体を伸ばす", "meregangkan badan")]),
 "shigoto-04": ("油や汚れがつく仕事ですが、大丈夫ですか。", "Pekerjaan ini terkena oli dan kotoran, apakah Anda baik-baik saja?", "はい、大丈夫です。作業のあとで、手や体をきれいに洗います。作業服もよく洗います。", "Ya, tidak masalah. Setelah kerja saya mencuci tangan dan badan hingga bersih. Pakaian kerja juga saya cuci.", [("油", "oli/minyak"), ("汚れ", "kotoran"), ("作業服", "pakaian kerja")]),
 "shigoto-05": ("体力が必要な仕事ですが、大丈夫ですか。", "Pekerjaan ini butuh stamina, apakah Anda baik-baik saja?", "はい、大丈夫です。毎日運動をして、体力をつけています。重い部品は、一人で持たないようにします。", "Ya, tidak masalah. Saya berolahraga setiap hari. Suku cadang berat tidak saya angkat sendirian.", [("体力", "stamina"), ("部品", "suku cadang"), ("重い", "berat")]),
 "shigoto-06": ("車検の前など、忙しい時期は残業があっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan lembur saat sibuk, misalnya menjelang inspeksi kendaraan?", "はい、大丈夫です。忙しい時期は、チームでがんばります。ただ、決まりは守りたいです。", "Ya, tidak masalah. Saat sibuk kami berusaha bersama. Namun saya ingin tetap mematuhi aturan.", [("車検", "inspeksi kendaraan"), ("残業", "lembur"), ("繁忙期", "musim sibuk")]),
 "shigoto-07": ("工具や機械を使うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memakai perkakas dan mesin?", "使う前に、工具が壊れていないか確認します。使ったあとは、決まった場所に戻します。", "Sebelum dipakai saya memeriksa apakah perkakas rusak. Setelah dipakai saya mengembalikannya ke tempat yang ditentukan.", [("工具", "perkakas"), ("確認", "memastikan"), ("戻す", "mengembalikan")]),
 "shigoto-08": ("大きい音や、油のにおいがある環境でも大丈夫ですか。", "Apakah Anda baik-baik saja di lingkungan yang bising dan berbau oli?", "はい、大丈夫です。必要なときは、耳せんやマスクをつけます。", "Ya, tidak masalah. Bila perlu saya memakai penyumbat telinga dan masker.", [("音", "suara"), ("におい", "bau"), ("耳せん", "penyumbat telinga")]),
 "shigoto-09": ("お客様の車を整備するとき、大切なことは何だと思いますか。", "Menurut Anda, apa yang penting saat merawat mobil pelanggan?", "安全にかかわるので、確認を忘れないことだと思います。お客様の車を、大切に扱います。", "Karena menyangkut keselamatan, saya kira tidak boleh lupa memeriksa. Saya memperlakukan mobil pelanggan dengan hati-hati.", [("安全", "keselamatan"), ("確認", "pengecekan"), ("大切に", "dengan hati-hati")]),
 "shigoto-10": ("車の点検では、どんなところを見ますか。", "Bagian apa saja yang diperiksa saat inspeksi mobil?", "ブレーキ、タイヤ、オイル、ライトなどを見ます。先輩に、チェック表を使って教えてもらいたいです。", "Saya memeriksa rem, ban, oli, lampu, dan sebagainya. Saya ingin diajari senior memakai daftar periksa.", [("ブレーキ", "rem"), ("チェック表", "daftar periksa"), ("ライト", "lampu")]),
 "shigoto-11": ("故障の原因が分からないとき、どうしますか。", "Apa yang Anda lakukan kalau tidak tahu penyebab kerusakan?", "勝手に直さないで、先輩に相談します。どんな音や様子だったか、メモして伝えます。", "Saya tidak memperbaiki sembarangan dan berkonsultasi dengan senior. Saya mencatat bunyi dan gejalanya lalu menyampaikannya.", [("原因", "penyebab"), ("相談", "konsultasi"), ("様子", "kondisi/gejala")]),
 "shigoto-12": ("お客様の車の取り扱いで、気をつけることは何ですか。", "Apa yang perlu diperhatikan dalam memperlakukan mobil pelanggan?", "傷をつけないように、カバーをかけます。車の中のものにも、勝手にさわりません。", "Saya memasang penutup agar tidak tergores. Barang di dalam mobil pun tidak saya sentuh sembarangan.", [("傷", "goresan"), ("カバー", "penutup"), ("さわる", "menyentuh")]),
 "shigoto-13": ("整備した車を返すとき、大切なことは何ですか。", "Apa yang penting saat mengembalikan mobil yang sudah diservis?", "最後にもう一度確認することです。直したところを、分かりやすく説明できるようにしたいです。", "Memeriksa sekali lagi di akhir. Saya ingin bisa menjelaskan bagian yang diperbaiki dengan jelas.", [("最終確認", "pengecekan akhir"), ("説明", "penjelasan"), ("お客様", "pelanggan")]),
 "taiou-02": ("車の部品を間違えて、つけてしまったら、どうしますか。", "Apa yang Anda lakukan kalau keliru memasang suku cadang?", "すぐに正直に先輩に報告します。やり直して、次は部品の番号を確認します。", "Saya segera melapor jujur kepada senior. Saya mengulang pekerjaan dan lain kali memeriksa nomor suku cadang.", [("部品", "suku cadang"), ("間違える", "keliru"), ("やり直す", "mengulang"), ("番号", "nomor")]),
 "taiou-06": ("急な修理の仕事が入ったら、どうしますか。", "Apa yang Anda lakukan kalau ada pekerjaan perbaikan mendadak?", "責任者の指示をよく聞いて、安全に気をつけて作業します。わからないときは、すぐに聞きます。", "Saya mendengarkan instruksi penanggung jawab dan bekerja dengan memperhatikan keselamatan. Kalau tidak paham, saya segera bertanya.", [("急な", "mendadak"), ("修理", "perbaikan"), ("指示", "instruksi")]),
 "taiou-08": ("お客様に、いつ直るか聞かれたら、どうしますか。", "Apa yang Anda lakukan kalau pelanggan bertanya kapan mobilnya selesai?", "自分で答えないで、先輩か責任者に伝えます。お客様には、少し待ってもらうようにお願いします。", "Saya tidak menjawab sendiri, tetapi menyampaikan kepada senior atau penanggung jawab. Saya meminta pelanggan menunggu sebentar.", [("お客様", "pelanggan"), ("責任者", "penanggung jawab"), ("お待ちください", "mohon tunggu")]),
 "taiou-11": ("忙しい時期で、疲れているとき、どう気持ちを保ちますか。", "Bagaimana Anda menjaga semangat saat sibuk dan lelah?", "忙しい時期は短いと理解しています。しっかり寝て、食事をとって、体調を保ちます。", "Saya paham musim sibuk itu singkat. Saya tidur cukup, makan baik, dan menjaga kondisi badan.", [("疲れる", "lelah"), ("体調", "kondisi badan"), ("睡眠", "tidur")]),
 "taiou-12": ("先輩が早口で説明して、分からないとき、どうしますか。", "Apa yang Anda lakukan kalau senior menjelaskan dengan cepat dan Anda tidak paham?", "「すみません、もう一度ゆっくりお願いします」と言います。分からない言葉は、メモして、あとで聞きます。", "Saya bilang \"Maaf, tolong ulangi lebih pelan\". Kata yang tidak paham saya catat dan tanyakan nanti.", [("早口", "bicara cepat"), ("ゆっくり", "pelan"), ("メモ", "catatan")]),
 "tim-01": ("忙しいとき、チームの人と、どのように作業を分けますか。", "Saat sibuk, bagaimana Anda membagi pekerjaan dengan tim?", "責任者の指示で、車ごとに担当を決めます。早く終わったら、ほかの人を手伝います。", "Sesuai instruksi penanggung jawab, tugas dibagi per mobil. Kalau selesai lebih dulu, saya membantu yang lain.", [("担当", "penanggung jawab tugas"), ("分担", "pembagian"), ("手伝う", "membantu")]),
 "tim-02": ("作業の順番が分からなかったとき、どうしますか。", "Apa yang Anda lakukan kalau tidak tahu urutan pekerjaan?", "すぐに先輩に聞きます。順番を間違えると、事故になることがあるからです。", "Saya segera bertanya kepada senior. Karena salah urutan bisa menyebabkan kecelakaan.", [("順番", "urutan"), ("間違える", "keliru"), ("事故", "kecelakaan")]),
 "tim-03": ("先輩や他の整備士と、どのようにコミュニケーションをとりますか。", "Bagaimana Anda berkomunikasi dengan senior dan mekanik lain?", "作業の前と後に、報告と連絡をします。分からないことは、小さいことでも相談します。", "Sebelum dan sesudah kerja saya melapor dan menghubungi. Hal yang tidak paham, sekecil apa pun, saya konsultasikan.", [("整備士", "mekanik"), ("報告", "melapor"), ("連絡", "menghubungi")]),
 "tim-04": ("工場の仲間と、どのように仲良くなりたいですか。", "Bagaimana Anda ingin akrab dengan rekan di bengkel?", "毎日、元気にあいさつをします。教えてもらったときは、「ありがとうございます」と言います。", "Setiap hari saya menyapa dengan semangat. Saat diajari, saya mengatakan \"Terima kasih\".", [("あいさつ", "salam"), ("仲間", "rekan"), ("感謝", "rasa terima kasih")]),
 "anzen-01": ("作業をするとき、必ず身につけるものは何ですか。", "Apa yang wajib dikenakan saat bekerja?", "作業服と安全靴を必ず着けます。必要なときは、手袋や保護めがねも使います。", "Saya wajib memakai pakaian kerja dan sepatu keselamatan. Bila perlu saya juga memakai sarung tangan dan kacamata pelindung.", [("安全靴", "sepatu keselamatan"), ("手袋", "sarung tangan"), ("保護めがね", "kacamata pelindung")]),
 "anzen-02": ("車を持ち上げるとき、何に気をつけますか。", "Apa yang Anda perhatikan saat mengangkat mobil?", "決まった場所にジャッキをかけて、必ず支えを使います。車の下に入るときは、特に注意します。", "Saya memasang dongkrak di titik yang ditentukan dan selalu memakai penyangga. Saat masuk ke bawah mobil saya sangat berhati-hati.", [("ジャッキ", "dongkrak"), ("支え", "penyangga"), ("車の下", "kolong mobil")]),
 "anzen-03": ("油や薬品を使うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memakai oli dan bahan kimia?", "火の近くでは使いません。こぼしたら、すぐに拭いて、床がすべらないようにします。使ったあとは、手を洗います。", "Saya tidak memakainya dekat api. Kalau tumpah, segera saya lap supaya lantai tidak licin. Setelah dipakai, saya cuci tangan.", [("薬品", "bahan kimia"), ("火", "api"), ("こぼす", "menumpahkan")]),
 "anzen-04": ("エンジンが動いているとき、近くで作業するときはどうしますか。", "Apa yang Anda lakukan saat bekerja dekat mesin yang sedang menyala?", "髪や服が巻き込まれないように気をつけます。回っている部分には、手を近づけません。", "Saya berhati-hati agar rambut dan pakaian tidak tertarik. Saya tidak mendekatkan tangan ke bagian yang berputar.", [("巻き込まれる", "terjerat/tertarik"), ("回る", "berputar"), ("気をつける", "berhati-hati")]),
 "seikatsu-07": ("車が多い町での生活に、不便なことがあっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan ketidaknyamanan hidup di kota yang banyak mobil?", "大丈夫です。交通ルールをよく勉強して、気をつけて歩きます。自転車に乗るときも、ルールを守ります。", "Tidak masalah. Saya akan mempelajari aturan lalu lintas dan berjalan dengan hati-hati. Saat naik sepeda saya juga menaati aturan.", [("交通ルール", "aturan lalu lintas"), ("自転車", "sepeda"), ("守る", "menaati")]),
 "seikatsu-08": ("日本の車や交通について、知っていることはありますか。", "Apa yang Anda ketahui tentang mobil dan lalu lintas di Jepang?", "日本では、車が左側を走ると聞きました。車検という決まりがあることも知っています。", "Saya dengar di Jepang mobil melaju di sisi kiri. Saya juga tahu ada aturan inspeksi kendaraan bernama shaken.", [("左側", "sisi kiri"), ("車検", "inspeksi kendaraan"), ("運転", "mengemudi")]),
 "mokuhyou-05": ("日本で自動車整備を学んだあと、自分の国でどんなことをしたいですか。", "Setelah belajar perawatan mobil di Jepang, apa yang ingin Anda lakukan di negara sendiri?", "日本で学んだ整備の技術と、安全の考え方を使って、自分の国でも車の整備の仕事がしたいです。", "Saya ingin memakai teknik servis dan cara berpikir keselamatan yang saya pelajari di Jepang untuk bekerja di bidang servis mobil di negara saya.", [("技術", "teknik"), ("考え方", "cara berpikir"), ("整備", "servis")]),
})
